/* Know Your Candidate - one state's page, and the directory of states.
 *
 * The page is generated by kyc/pages.py with its names written in as plain
 * lists, for a reader without scripts and for a crawler (rule 96); what a
 * reader with scripts sees is rendered here over them, from the same
 * build's people files the grid and the map load, so a state page can never
 * disagree with them about who represents a district. Which page this is
 * comes from <body data-page="state" data-state="TX"> or
 * <body data-page="states">.
 */
(function (global) {
  "use strict";

  var doc = global.document;
  var KYC = global.KYC;
  var data = KYC.people();
  var races = KYC.races();
  var cards = KYC.cards;

  var code = doc.body.getAttribute("data-state") || "";
  var kind = doc.body.getAttribute("data-page") || "state";

  function el(id) {
    return doc.getElementById(id);
  }

  function plural(n, word, words) {
    return n + " " + (n === 1 ? word : (words || word + "s"));
  }

  /* ------------------------------------------------------------ one state */

  function peopleIn(race) {
    return race.incumbentIds.concat(race.candidateIds).map(KYC.byId).filter(Boolean);
  }

  function districtLabel(race) {
    if (race.chamber === "Senate") return "U.S. Senate";
    if (!race.district) return "At-large seat";
    return "District " + race.district;
  }

  /* A race's name as a jump chip or a folded row's number gives it. */
  function shortLabel(race) {
    return race.chamber === "Senate" ? "Senate" : (race.district ? String(race.district) : "At-large");
  }

  /* --------------------------------------- a big state's races on a phone */

  /* On a phone California's page was about 92 screens once drawn, its
   * district squares 13,900px down, and every seated member's card twice
   * (VISUALS-15, TECH-14). Below 1000px, a state with more than FOLD_OVER
   * races opens with a "Find your race" block under its summary and folds
   * each race to one row whose section stays in the page below it, hidden
   * until found. 1000px and wider, the page is as it was. */
  var FOLD_OVER = 4;
  var FOLD_QUERY = "(max-width: 999.98px)";

  /** The block itself, drawn hidden: foldLayout shows it on a phone and
   *  moves the district squares and "Find who represents you" into it.
   *  The names in it are a heading's, a race's or a table's elsewhere on
   *  the page (rules 48, 75). *seated*: the state's sitting House members,
   *  the delegation's own list. */
  function findRaceBlock(info, senateRaces, houseRaces, measures, parts, seated, govRace) {
    var opt = function (id, text) {
      return '<option value="' + KYC.escapeAttr(id) + '">' + KYC.escapeHtml(text) + "</option>";
    };
    var vacancies = {};
    (info.vacancies || []).forEach(function (v) { vacancies[v.district] = true; });
    // Who sits for each district now, as the House delegation lists them
    // (rule 27): never the frozen record's incumbent, who from January 3
    // may sit in the Senate or for another district (rule 67).
    var sitting = {};
    (seated || []).forEach(function (p) {
      var n = p.districtNum === null || p.districtNum === undefined ? 0 : p.districtNum;
      (sitting[n] || (sitting[n] = [])).push(p.name);
    });
    var offices = KYC.stategov && KYC.stategov.ballotOffices ? KYC.stategov.ballotOffices(code) : null;
    var statewide = senateRaces.map(function (race) { return ["race-" + race.id, districtLabel(race)]; })
      .concat(offices ? [["state-government", govHeading(info) + ": " + offices]] : [])
      .concat(measures ? [["measures", KYC.ballot.measuresName(code)]] : []);
    var house = houseRaces.map(function (race) {
      var names = sitting[race.district || 0];
      var who = names ? " · held by " + names.join(" and ") : vacancies[race.district] ? " · vacant" : "";
      return opt("race-" + race.id, districtLabel(race) + who);
    }).join("");
    // The page's own sections, by the names their jump chips give them,
    // less those the Statewide group already offers; the voting block's is
    // added once it is drawn (foldLayout).
    var listed = {};
    statewide.forEach(function (s) { listed[s[0]] = true; });
    // The race for governor, by its own heading's words, in the Statewide
    // group only: the line under the select names the office already.
    var governor = govRace ? [["race-governor", KYC.stategov.raceHeading(code)]] : [];
    if (govRace) listed["governor-race"] = true;
    // In page order, as the jump bar's copy offers them too: the race for
    // governor follows the races for Congress and comes before the
    // statewide questions, so it goes before them in the group.
    var options = statewide.filter(function (s) { return s[0] !== "measures"; }).concat(governor)
      .concat(statewide.filter(function (s) { return s[0] === "measures"; }));
    var here = parts.filter(function (p) { return !listed[p[0]]; })
      .map(function (p) { return opt(p[0], p[1]); }).join("");
    var line = statewide.map(function (s) {
      return '<a class="state-jump" href="#' + KYC.escapeAttr(s[0]) + '">' +
        KYC.escapeHtml(s[0] === "state-government" ? offices : s[1]) + "</a>";
    }).join(" · ");
    // Only what this site covers, and said so (as officesAlso does): the
    // line read as the whole statewide ballot, without Texas's comptroller
    // or California's controller. In the past tense from the day after
    // Election Day (rule 84).
    var past = KYC.electionStatus(2026).phase === "post-election";
    return '<section class="state-section find-race" id="find-race" aria-labelledby="findRaceHead" hidden>' +
      '<h2 class="state-heading" id="findRaceHead">Find your race</h2>' +
      '<div class="race-jump find-race-jump"><label for="raceJumpSelect">Jump to a race or section</label>' +
      '<select id="raceJumpSelect" class="select" data-race-jump>' +
      '<option value="">Choose…</option>' +
      (options.length ? '<optgroup label="Statewide">' +
        options.map(function (s) { return opt(s[0], s[1]); }).join("") + "</optgroup>" : "") +
      (house ? '<optgroup label="U.S. House">' + house + "</optgroup>" : "") +
      '<optgroup label="This page" data-this-page>' + here + "</optgroup></select></div>" +
      '<div class="find-race-tiles"></div><div class="find-race-lookup"></div>' +
      (line ? '<p class="find-race-statewide"><span class="find-race-kicker">Of what this site covers, ' +
        "the Nov 3, 2026 ballot " + (past ? "held" : "holds") + " statewide:</span> " + line +
        '. <span class="find-race-more">It may also ' + (past ? "have held " : "hold ") +
        KYC.escapeHtml(KYC.ballot.unlisted) + ".</span></p>" : "") +
      "</section>";
  }

  /* The fold's state: whether the page is folded now, which races are
   * open and why ("reader", "search", "find", "print"), and where the
   * parts the block borrows live when it is not. Nothing is stored. */
  var fold = null;

  function foldQuery() {
    try {
      return global.matchMedia ? global.matchMedia(FOLD_QUERY) : null;
    } catch (e) {
      return null;
    }
  }

  function initFold() {
    var content = el("stateContent");
    var findrep = el("findrep");
    var tiles = content.querySelector(".race-tiles");
    var links = content.querySelector(".state-hero .state-links");
    fold = {
      phone: null,
      opened: {},
      // Who opened the folded House delegation, or null while it is folded.
      delegation: null,
      // Each borrowed part goes back before what followed it.
      homes: [findrep, tiles, links].filter(Boolean).map(function (node) {
        return { node: node, parent: node.parentNode, next: node.nextSibling };
      }),
    };
    // The voting block's own heading names it in the select.
    var voting = el("votingHead");
    var group = content.querySelector("[data-this-page]");
    if (voting && group) {
      var option = doc.createElement("option");
      option.value = "voting";
      option.textContent = voting.textContent.trim();
      group.insertBefore(option, group.firstChild);
    }
    initJumpBar();
    foldLayout();
    var query = foldQuery();
    if (query) {
      if (query.addEventListener) query.addEventListener("change", foldLayout);
      else if (query.addListener) query.addListener(foldLayout);
    }
  }

  /* -------------------------------------------- the jump bar on a phone */

  /* Once "Find your race" has scrolled away, getting to a second race meant
   * scrolling back up as much as fifteen screens. A bar under the header
   * then holds the same select and a way back to the block. It is fixed,
   * so showing it moves nothing on the page, and while it shows the page's
   * scroll-padding grows by its height, so every jump lands below it (rule
   * 44). Not on a screen shorter than 500px (a phone on its side), where
   * the header and the bar would take a third of it. Nothing is stored. */
  var SHORT_QUERY = "(max-height: 499.98px)";
  var jumpBar = null;

  function initJumpBar() {
    var block = el("find-race");
    var select = el("raceJumpSelect");
    if (!block || !select) return;
    var bar = doc.createElement("nav");
    bar.className = "jumpbar";
    bar.setAttribute("aria-label", "Jump to");
    bar.hidden = true;
    // The block's own select, copied once it holds every option (the
    // voting block's is added in initFold): one list, two places.
    var copy = select.cloneNode(true);
    copy.id = "raceJumpBar";
    copy.setAttribute("aria-label", "Jump to a race or section");
    copy.options[0].textContent = "Jump to…";
    bar.appendChild(copy);
    var back = doc.createElement("button");
    back.type = "button";
    back.className = "btn jumpbar-back";
    back.setAttribute("data-jump-find", "");
    back.innerHTML = '<span aria-hidden="true">↑</span> Find your race';
    bar.appendChild(back);
    el("stateContent").appendChild(bar);
    jumpBar = { bar: bar, past: false, short: null };
    try {
      jumpBar.short = global.matchMedia ? global.matchMedia(SHORT_QUERY) : null;
    } catch (e) {
      jumpBar.short = null;
    }
    if (jumpBar.short) {
      if (jumpBar.short.addEventListener) jumpBar.short.addEventListener("change", showJumpBar);
      else if (jumpBar.short.addListener) jumpBar.short.addListener(showJumpBar);
    }
    if (!global.IntersectionObserver) return;
    // Past the block once its bottom is under the header.
    var header = doc.querySelector(".app-header");
    var top = header ? Math.round(header.getBoundingClientRect().height) : 0;
    new global.IntersectionObserver(function (entries) {
      var entry = entries[entries.length - 1];
      jumpBar.past = !entry.isIntersecting && entry.boundingClientRect.top < top;
      showJumpBar();
    }, { rootMargin: "-" + top + "px 0px 0px 0px" }).observe(block);
  }

  function showJumpBar() {
    if (!jumpBar) return;
    var show = !!(fold && fold.phone && jumpBar.past && !(jumpBar.short && jumpBar.short.matches));
    if (jumpBar.bar.hidden === !show) return;
    jumpBar.bar.hidden = !show;
    var root = doc.documentElement;
    root.classList.toggle("has-jumpbar", show);
    if (show) {
      var height = Math.round(jumpBar.bar.getBoundingClientRect().height);
      if (height) root.style.setProperty("--jump-h", height + "px");
    }
  }

  /** Before a jump to *target*: show the bar, and its padding, if the
   *  jump will leave "Find your race" above the screen, and hide it if
   *  not. Set only once the observer saw the block go, the padding came a
   *  moment after every jump made from the block or by a link - its
   *  select, a square, the lookup's answer, a #race- address - and the bar
   *  then covered the top of the race the jump had landed on (PR #176
   *  review). The observer still has the last word as the page moves. */
  function barForJump(target) {
    if (!jumpBar || !target) return;
    var block = el("find-race");
    if (!block || block.hidden) return;
    // 4: DOCUMENT_POSITION_FOLLOWING - the target comes after the block.
    jumpBar.past = target !== block && !block.contains(target) &&
      !!(block.compareDocumentPosition(target) & 4);
    showJumpBar();
  }

  /* Every part of the page that folds to a row: the races for Congress,
   * and the race for governor, which is no race for Congress and stays out
   * of their count ("Open all 52 races") and their checks (rule 73). */
  var FOLDS = "section.race-foldable, section.gov-race-foldable";

  function raceSections() {
    return Array.prototype.slice.call(doc.querySelectorAll("#stateContent section.race-foldable"));
  }

  /* The race for governor's section holds its one folding race: a link to
   * the section ("#governor-race", from State government) opens it. */
  function ownFold(node) {
    return node && node.id === "governor-race" ? node.querySelector("section.gov-race-foldable") : null;
  }

  function foldSections() {
    return Array.prototype.slice.call(doc.querySelectorAll("#stateContent section.race-foldable, " +
      "#stateContent section.gov-race-foldable"));
  }

  /** Fold the page for the width it is drawn at, or unfold it: moving the
   *  borrowed parts, never redrawing them, so a lookup's answer and an
   *  opened race survive a turned tablet. */
  function foldLayout() {
    if (!fold) return;
    var query = foldQuery();
    var phone = !!(query && query.matches);
    if (fold.phone === phone) return;
    fold.phone = phone;
    var content = el("stateContent");
    var block = el("find-race");
    block.hidden = !phone;
    fold.homes.forEach(function (home) {
      if (phone) {
        var slot = home.node.classList.contains("findrep") ? block.querySelector(".find-race-lookup")
          : home.node.classList.contains("race-tiles") ? block.querySelector(".find-race-tiles") : null;
        if (slot) slot.appendChild(home.node);
        // The header's links follow the block.
        else block.parentNode.insertBefore(home.node, block.nextSibling);
      } else {
        home.parent.insertBefore(home.node, home.next && home.next.parentNode === home.parent ? home.next : null);
      }
    });
    ["races", "governor-race"].forEach(function (id) {
      if (el(id)) el(id).classList.toggle("races-folded", phone);
    });
    Array.prototype.forEach.call(content.querySelectorAll(".state-parts, .race-jumps"), function (nav) {
      nav.hidden = phone;
    });
    Array.prototype.forEach.call(content.querySelectorAll(".race-fold-bar"), function (bar) {
      bar.hidden = !phone;
    });
    foldSections().forEach(function (section) {
      section.querySelector(".race-row-title").hidden = !phone;
      section.querySelector(".race-close-row").hidden = !phone;
      section.hidden = false;
      showBody(section, !phone || !!fold.opened[section.getAttribute("data-race")]);
    });
    showDelegation(!phone || !!fold.delegation);
    // A search in the box holds on a turned tablet: the two layouts must
    // not disagree about what it shows.
    searchRaces(searchQuery());
    openAllWords();
    showJumpBar();
  }

  /* On a phone the House delegation's cards fold behind their heading,
   * which keeps its balance ("43 D / 9 R"), and a button that shows them:
   * California's 52 cards were some 8,000px between the reader and the
   * races. The senators stay open, every race's row leads with who holds
   * its seat, and "Find who represents you" answers above (rule 27). The
   * cards stay in the page, hidden until found, as a race's body does. */
  function showDelegation(open) {
    var grid = el("delegationCards");
    var button = doc.querySelector("[data-delegation-toggle]");
    if (!grid || !button) return;
    if (open) grid.removeAttribute("hidden");
    else grid.setAttribute("hidden", "until-found");
    button.parentNode.hidden = !fold.phone;
    button.setAttribute("aria-expanded", String(open));
    var count = button.getAttribute("data-count");
    button.textContent = (open ? "Fold the " : "Show all ") + count;
  }

  function setDelegation(open, why) {
    if (!fold || !el("delegationCards")) return;
    fold.delegation = open ? (fold.delegation || why || "reader") : null;
    if (fold.phone) showDelegation(open);
  }

  function showBody(section, open) {
    var body = section.querySelector(".race-body");
    if (open) body.removeAttribute("hidden");
    else body.setAttribute("hidden", "until-found");
    section.querySelector(".race-row").setAttribute("aria-expanded", String(open));
    section.classList.toggle("is-open", open);
  }

  /** Open or fold one race; *why* is who opened it, so the page search
   *  folds back only what it opened. */
  function setOpen(section, open, why) {
    if (!fold || !section) return;
    var id = section.getAttribute("data-race");
    if (open) fold.opened[id] = fold.opened[id] || why || "reader";
    else delete fold.opened[id];
    if (fold.phone) showBody(section, open);
    openAllWords();
  }

  /** The races the button opens and folds: those shown. Under a filter or
   *  a search it said "Open all 52 races" below "Showing 4 of 52 races",
   *  and opened the 48 hidden ones too (rule 73; PR #176 review). */
  function shownSections() {
    return raceSections().filter(function (s) { return !s.hidden; });
  }

  function openAllWords() {
    var button = doc.querySelector("[data-race-open-all]");
    if (!button || !fold) return;
    var sections = shownSections();
    var every = sections.length === raceSections().length;
    var all = sections.length && sections.every(function (s) { return !!fold.opened[s.getAttribute("data-race")]; });
    var what = sections.length === 1 ? "this race" : (every ? "all " : "these ") + plural(sections.length, "race");
    button.textContent = (all ? "Fold " : "Open ") + what;
    button.setAttribute("aria-pressed", String(!!all));
    button.hidden = !sections.length;
  }

  /** Bring *id* into view - a race opened first where the page folds -
   *  and put the reader there: on a race's row, or on the section. */
  function goTo(id) {
    var target = doc.getElementById(id);
    if (!target) return null;
    var section = (target.closest ? target.closest(FOLDS) : null) || ownFold(target);
    // A race the filter left out is shown with all the others: a jump to
    // a race must never land on nothing.
    if (section && fold && fold.phone && !filterPasses(section)) setRaceFilter("all");
    if (section && fold && fold.phone) setOpen(section, true, "reader");
    // At once, never animated: a smooth scroll's end is worked out before
    // it starts, and the delegation's cards above the races grow as they
    // render on the way past (content-visibility), so a phone's jump to
    // CA-40 stopped 850px short, below the screen (PR #126 review). The
    // address's own #race- link was always instant and always landed.
    barForJump(target);
    if (target.scrollIntoView) target.scrollIntoView({ block: "start", behavior: "auto" });
    var focus = section && fold && fold.phone ? section.querySelector(".race-row") : target;
    if (focus.focus) {
      if (focus === target && !target.hasAttribute("tabindex")) target.setAttribute("tabindex", "-1");
      focus.focus({ preventScroll: true });
    }
    return target;
  }

  /* The select: a pick from a pointer jumps at once. Arrow keys on a closed
   * select change its value as they go, so a keyboard's pick jumps on
   * Enter, never on each arrow. The select goes back to "Choose…", so the
   * same race can be picked again. */
  function initJumpSelect() {
    // The block's, and the jump bar's copy of it.
    Array.prototype.forEach.call(doc.querySelectorAll("[data-race-jump]"), bindJumpSelect);
  }

  function bindJumpSelect(select) {
    var keyed = false;
    var go = function () {
      var id = select.value;
      if (!id) return;
      select.value = "";
      goTo(id);
    };
    select.addEventListener("keydown", function (event) {
      // Alt+Down, F4 and Space open the list itself, where a pick is a
      // pick: only a key that changes a closed select's value waits.
      if (event.altKey || event.key === "F4" || event.key === " ") keyed = false;
      else if (/^(Arrow|Page|Home$|End$)/.test(event.key)) keyed = true;
      if (event.key === "Enter" && select.value) {
        event.preventDefault();
        keyed = false;
        go();
      }
    });
    select.addEventListener("pointerdown", function () { keyed = false; });
    select.addEventListener("change", function () {
      if (keyed) {
        keyed = false;
        return;
      }
      go();
    });
  }

  /* The browser's find opens a race it found a word in (hidden until
   * found), and its row says so; printing opens every race, and folds back
   * what it opened. */
  function initFoldEvents() {
    doc.addEventListener("beforematch", function (event) {
      var section = event.target && event.target.closest && event.target.closest(FOLDS);
      if (section) setOpen(section, true, "find");
      if (event.target && event.target.id === "delegationCards") setDelegation(true, "find");
    }, true);
    global.addEventListener("beforeprint", function () {
      if (!fold || !fold.phone) return;
      if (!fold.delegation) setDelegation(true, "print");
      foldSections().forEach(function (s) {
        if (!fold.opened[s.getAttribute("data-race")]) setOpen(s, true, "print");
      });
    });
    global.addEventListener("afterprint", function () {
      if (!fold) return;
      if (fold.delegation === "print") setDelegation(false);
      foldSections().forEach(function (s) {
        if (fold.opened[s.getAttribute("data-race")] === "print") setOpen(s, false);
      });
    });
    // A link to a race on this page, followed after it has loaded (an
    // address typed or pasted, a link from another script).
    global.addEventListener("hashchange", function () {
      if (/^#(race-|governor)/.test(global.location.hash)) jumpToSection();
    });
  }

  /* ------------------------------------------- filters over the race rows */

  /* On a phone, chips over the rows pick out the open seats and the races
   * with no challenger on the ballot, counted by the race heads' own tests
   * (KYC.cards.raceFilters, rule 73), with a live line saying how many are
   * shown and a way back to all of them. The filter is in the address
   * (#/?races=open), so a shared link shows the same rows. */
  var raceFilter = "all";

  /** A chip's words: the head badge's own words for the races it keeps
   *  (KYC.cards.raceFilterWords, one helper, rule 12). */
  function filterWords(key) {
    return cards.raceFilterWords(key);
  }

  function raceFilterBar(list) {
    var counts = cards.raceFilterCounts(list);
    var keys = ["all"].concat(Object.keys(cards.raceFilters).filter(function (k) { return counts[k]; }));
    if (keys.length < 2) return "";
    return '<div class="race-filters" role="group" aria-label="Show races for Congress">' + keys.map(function (k) {
      return '<button type="button" class="chip race-filter" data-race-filter="' + k + '" aria-pressed="' +
        String(k === "all") + '">' + KYC.escapeHtml(filterWords(k)) +
        ' <span class="race-filter-count">' + counts[k] + "</span></button>";
    }).join("") + "</div>" +
      '<p class="race-filter-status"><span id="raceFilterStatus" role="status" aria-live="polite"></span> ' +
      '<button type="button" class="link-button race-filter-all" data-race-filter="all" hidden>Show all</button></p>';
  }

  function raceById(id) {
    return races.filter(function (r) { return r.id === id; })[0] || null;
  }

  /* The chips pick out races for Congress, by the race heads' tests: the
   * race for governor (section.gov-race-foldable) is none of them, so no
   * chip counts it or hides it (rules 27, 73). */
  function filterPasses(section) {
    if (raceFilter === "all" || !cards.raceFilters[raceFilter]) return true;
    if (!section.classList.contains("race-foldable")) return true;
    var race = raceById(section.getAttribute("data-race"));
    return !!race && cards.raceFilters[raceFilter](race);
  }

  /** Pick out *key*'s races ("all" for every one). *quiet*: from the
   *  address, which already says so. */
  function setRaceFilter(key, quiet) {
    var chip = doc.querySelector('.race-filters [data-race-filter="' + key + '"]');
    if (!chip || !cards.raceFilters[key]) key = "all";
    raceFilter = key;
    Array.prototype.forEach.call(doc.querySelectorAll(".race-filters [data-race-filter]"), function (b) {
      b.setAttribute("aria-pressed", String(b.getAttribute("data-race-filter") === key));
    });
    searchRaces(searchQuery());
    filterStatus();
    if (!quiet && KYC.router) KYC.router.writeFilters({ races: key });
  }

  function filterStatus() {
    var status = el("raceFilterStatus");
    if (!status) return;
    var sections = raceSections();
    var shown = sections.filter(function (s) { return !s.hidden; }).length;
    var on = raceFilter !== "all" && !!(fold && fold.phone);
    var words = on ? "Showing " + shown + " of " + plural(sections.length, "race") + " for Congress" : "";
    if (status.textContent !== words) status.textContent = words;
    var all = doc.querySelector(".race-filter-all");
    if (all) all.hidden = !on;
    openAllWords();
  }

  /* A non-voting member's title, as summary.py gives it: Puerto Rico's
   * Resident Commissioner is not a "delegate". */
  function delegateTitle(info) {
    return info.delegateTitle || "Delegate";
  }

  /* Who holds the state's seats, in words: the hero and the directory of
   * states say it the same way. */
  function seatWords(info) {
    var seats = [];
    if (info.senators) seats.push(plural(info.senators, "senator"));
    if (info.house) seats.push(plural(info.house, "representative"));
    if (info.delegates) {
      var title = delegateTitle(info);
      seats.push(plural(info.delegates, title === "Delegate" ? "delegate" : title));
    }
    return seats;
  }

  /* A House seat elected for longer than two years and not on this
   * cycle's ballot (Puerto Rico's): why it has no race, in place of the
   * zeros. */
  function offCycle(info) {
    var term = info.houseTerm;
    if (!term || info.races) return "";
    return delegateTitle(info) + ": a " + term.years + "-year term, next on the ballot in " + term.next;
  }

  function summaryStrip(info) {
    var parts = seatWords(info);
    if (offCycle(info)) {
      parts.push(offCycle(info));
      return badges(parts);
    }
    // Once the new Congress sits these are a record of 2026, and say so.
    var rec = KYC.recordPhase();
    parts.push(plural(info.seatsUp, "seat") + " in Congress on the 2026 ballot");
    if (info.open) parts.push(plural(info.open, "open seat") + (rec ? " in 2026" : ""));
    if (info.renumbered) {
      parts.push(plural(info.renumbered, "member") + " running under a new district number");
    }
    parts = parts.concat(runningWords(info, rec));
    if (info.challengersOut) {
      parts.push(plural(info.challengersOut, "candidate") + " out after the " +
        (rec ? "2026 " : "") + "primaries");
    }
    return badges(parts);
  }

  /** Who is on the ballot besides members running for their own seats, in
   *  the race headers' words: "challengers" where someone holds the seat on
   *  the ballot, "candidates" for an open seat, where nobody is challenging
   *  anyone. Wyoming's two open seats read "4 challengers" over two race
   *  heads that said "candidates" (audit 2026-10-17, RACES-14). The two
   *  figures sum to the race headers' total (summary.by_state, rule 73). */
  function runningWords(info, rec) {
    var where = rec ? " on the 2026 ballot" : " on the ballot";
    var open = info.openCandidates || 0;
    var held = (info.challengersOnBallot || 0) - open;
    var out = [];
    if ((held || !open) && (held || !info.challengersFiled)) out.push(plural(held, "challenger") + where);
    if (open) out.push(plural(open, "candidate") + " for open seats" + where);
    // Where there is no primary and no ballot list was read (a territory
    // whose list this site has no reader for): filed, which is not the same
    // claim, and says what was not done - it checked no list, which is not
    // to say none is published (rule 19). American Samoa read "0
    // challengers on the ballot" over six filers.
    if (info.challengersFiled) {
      out.push(plural(info.challengersFiled, "challenger") + " filed; ballot list not checked");
    }
    return out;
  }

  function badges(parts) {
    return parts.map(function (t) {
      return '<span class="badge badge-neutral">' + KYC.escapeHtml(t) + "</span>";
    }).join(" ");
  }

  /* The delegation by party. *vacant* is the state's empty seats, which
   * have no profile to count (summary.py counts them from the races), so
   * the heading agrees with the sidebar. */
  function balance(people, vacant) {
    var counts = { vacant: vacant || 0 };
    people.forEach(function (p) {
      var key = KYC.partyKey(p);
      counts[key] = (counts[key] || 0) + 1;
    });
    var order = [["r", "R"], ["d", "D"], ["i", "I"], ["vacant", "Vacant"]];
    return order.filter(function (o) { return counts[o[0]]; }).map(function (o) {
      return '<span class="party-' + o[0] + '">' + counts[o[0]] + " " + o[1] + "</span>";
    }).join('<span class="sep">/</span>');
  }

  /* The government section's name, for its heading and its jump chip
   * alike: D.C.'s is a local government, a territory's territorial. */
  function govHeading(info) {
    return code === "DC" ? "Local government" : info.territory ? "Territorial government" : "State government";
  }

  function renderState() {
    var target = el("stateContent");
    var info = (KYC.meta().states || {})[code];
    if (!info) {
      target.innerHTML = '<div class="empty-state"><h3>No such state</h3>' +
        "<p>Nothing in the data is filed under " + KYC.escapeHtml(code) + ".</p></div>";
      return;
    }
    var name = info.name;
    // The guide's page on state government, by the name it gives itself
    // (pages._state_main): never retyped here (rule 75).
    var guideName = target.getAttribute("data-guide-name") || "";
    doc.title = name + " — Know Your Candidate";
    // Every state links to its district map; a redrawn one says so.
    var districtMap = (KYC.meta().districtMaps || {})[code];

    // Who represents the state now (rule 27): never a former member.
    var members = data.filter(function (p) { return KYC.seated(p) && p.state === code; });
    var senators = members.filter(function (p) { return p.chamber.indexOf("Senate") !== -1; });
    var house = members.filter(function (p) { return p.chamber.indexOf("House") !== -1; })
      .sort(function (a, b) { return KYC.districtOrder(a) - KYC.districtOrder(b); });

    var stateRaces = races.filter(function (r) { return r.state === code; });
    var senateRaces = stateRaces.filter(function (r) { return r.chamber === "Senate"; });
    var houseRaces = stateRaces.filter(function (r) { return r.chamber === "House"; })
      .sort(function (a, b) { return (a.district || 0) - (b.district || 0); });
    // Where the races fold to rows on a phone (VISUALS-15), and the head
    // badges every race shares, said once above them there.
    var foldable = senateRaces.length + houseRaces.length > FOLD_OVER;
    var shared = foldable ? cards.sharedBadges(senateRaces.concat(houseRaces)) : {};
    // The race for governor, where the state's governor is on this ballot:
    // a section of its own after the races for Congress, as cards
    // (KYC.stategov.governorRace), folded to a row where they fold.
    var govRace = !!(KYC.stategov && KYC.stategov.governorUp && KYC.stategov.governorUp(code));

    // The statewide questions on the ballot (rule 95), after the races, as
    // a printed ballot puts them; "" where nothing is recorded.
    var measures = KYC.ballot.measuresSection(code);
    // Where data/measures.js did not load, the plain list the page was
    // written with stays, under a line saying so (rules 76, 96): drawn
    // from nothing, it vanished without a word (PR #123 review).
    var keptMeasures = false;
    if (!measures && KYC.ballot.measuresMissing()) {
      var written = target.querySelector("#measures");
      if (written) {
        var kept = written.cloneNode(true);
        var heading = kept.querySelector("h2");
        var holder = doc.createElement("div");
        holder.innerHTML = KYC.ballot.measuresFailedLine(code, true);
        if (heading) heading.parentNode.insertBefore(holder.firstChild, heading.nextSibling);
        else kept.insertBefore(holder.firstChild, kept.firstChild);
        measures = kept.outerHTML;
        keptMeasures = !!kept.querySelector("[data-measure]");
      }
    }

    var html = [];
    html.push(
      '<header class="state-hero">',
      '<p class="state-kicker">State &amp; territory pages</p>',
      '<h1 class="state-title">' + KYC.escapeHtml(name) + "</h1>",
      '<p class="state-summary">' + summaryStrip(info) + "</p>",
      '<p class="state-links">',
      '<a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "map.html#/?state=" + code) + '">' +
        KYC.icon("map") + " See on the map</a> ",
      '<a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "index.html#/?state=" + code) + '">' +
        KYC.icon("grid") + " All " + KYC.escapeHtml(name) + " profiles</a>",
      districtMap
        ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + districtMap.page) + '">' +
          KYC.icon("layers") + (districtMap.redrawn ? " Old and new district lines" :
            " District map") + "</a>"
        : "",
      // Every state - not D.C. or a territory - has a legislature page.
      info.senators
        ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "legislature/" +
          code.toLowerCase() + ".html") + '">' + KYC.icon("landmark") + " State legislature</a>" +
          ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "counties/" +
          code.toLowerCase() + ".html") + '">' + KYC.icon("layers") + " Counties &amp; local governments</a>" +
          (guideName ? ' <a class="btn" href="' + KYC.escapeAttr(KYC.siteRoot() + "government/states.html") +
            '">' + KYC.icon("scroll") + " " + KYC.escapeHtml(guideName) + "</a>" : "")
        : "",
      "</p>",
      "</header>"
    );
    /* Where each part of the page starts. On a phone Texas's House
     * delegation alone is 6,500px of cards, and the 2026 races began eleven
     * screens down with the only way to them inside the closed drawer. */
    var parts = [
      senators.length ? ["senators", "U.S. senators"] : null,
      house.length ? ["delegation", info.territory ? delegateTitle(info) : "House delegation"] : null,
      KYC.stategov && (KYC.stategov.state(code) || code === "DC") ? ["state-government", govHeading(info)] : null,
      senateRaces.length + houseRaces.length ? ["races", "2026 races"] : null,
      govRace ? ["governor-race", "Race for governor"] : null,
      measures ? ["measures", KYC.ballot.measuresName(code)] : null,
    ].filter(Boolean);
    if (foldable) html.push(findRaceBlock(info, senateRaces, houseRaces, measures, parts, house, govRace));
    if (parts.length > 1) {
      html.push('<nav class="toolbar jump-row state-parts" aria-label="On this page">' +
        parts.map(function (p) {
          return '<a class="chip chip-link" href="#' + p[0] + '">' + KYC.escapeHtml(p[1]) + "</a>";
        }).join("") + "</nav>");
    }

    // "Find who represents me" (kyc-findrep.js), and beside it the way to
    // the voting block below: a ZIP code or a location, answered at every
    // level, before the page lists the whole delegation.
    html.push('<section class="state-section findrep" id="findrep" data-findrep ' +
      'data-findrep-state="' + KYC.escapeAttr(code) + '"></section>');
    html.push(KYC.ballot.votingBlock(code, name));

    /* Who holds the seats now. Senators first, then the House by district;
     * a reader who asked "who represents me" gets the answer before the
     * page turns to who is running (rule 27). */
    if (senators.length) {
      html.push(
        '<section class="state-section" id="senators">',
        '<h2 class="state-heading">U.S. senators <span class="balance">' + balance(senators) + "</span></h2>",
        '<div class="card-grid">' + senators.map(cards.card).join("") + "</div>",
        "</section>"
      );
    }
    if (house.length) {
      html.push(
        '<section class="state-section" id="delegation">',
        '<h2 class="state-heading">' + (info.territory ? KYC.escapeHtml(delegateTitle(info)) +
          " to the U.S. House" : "U.S. House delegation") +
          ' <span class="balance">' + balance(house,
            ((info.balance || {}).house || {}).vacant) + "</span></h2>",
        offCycle(info)
          ? '<p class="state-note">' + KYC.escapeHtml(name) + " elects its " +
            KYC.escapeHtml(delegateTitle(info)) + " at large for a " + info.houseTerm.years +
            '-year term (<a href="https://www.law.cornell.edu/uscode/text/48/891" target="_blank" ' +
            'rel="noopener noreferrer">48 U.S.C. § 891</a>). The seat was last on the ballot in ' +
            info.houseTerm.last + " and is next in " + info.houseTerm.next + ", so no seat in Congress " +
            "is on " + KYC.escapeHtml(KYC.possessive(name)) + " 2026 ballot.</p>"
          : "",
        // Each empty seat: who left, when, and whether a special election
        // has been called (summary.py, overrides.SEAT_VACANCIES).
        (info.vacancies || []).map(function (v) {
          return '<p class="state-note">District ' + v.district + ": " +
            KYC.escapeHtml(KYC.vacancyNote(v)) + "</p>";
        }).join(""),
        // On a phone (foldLayout), the cards fold behind a button.
        foldable
          ? '<p class="delegation-fold" hidden><button type="button" class="btn delegation-toggle" ' +
            'data-delegation-toggle aria-controls="delegationCards" aria-expanded="true" data-count="' +
            KYC.escapeAttr(plural(house.length, "representative")) + '">Fold the ' +
            KYC.escapeHtml(plural(house.length, "representative")) + "</button></p>"
          : "",
        '<div class="card-grid"' + (foldable ? ' id="delegationCards"' : "") + ">" +
          house.map(cards.card).join("") + "</div>",
        "</section>"
      );
    }

    /* Who runs the state itself: drawn by the module the map's state views
     * use, so the two say the same thing. */
    if (KYC.stategov && (KYC.stategov.state(code) || code === "DC")) {
      html.push(
        '<section class="state-section" id="state-government">',
        '<h2 class="state-heading">' + govHeading(info) + "</h2>",
        // The three branches at a glance, the details under them (VISUALS-28).
        KYC.stategov.glance ? KYC.stategov.glance(code) : "",
        // The governor's card here, with the anchor links reach it by; the
        // race for governor in its own section below (governorSection).
        '<div class="stategov">' + KYC.stategov.render(code, { links: false, here: true, raceApart: govRace }) +
          "</div>",
        "</section>"
      );
    }

    /* The 2026 races, one section each, in ballot order. Each race's
     * markets are closed until opened (cards.raceSection): as tall as its
     * people, they made California's page about 60 screens long on a phone
     * (VISUALS-15). */
    var raceHtml = senateRaces.concat(houseRaces).map(function (race) {
      var people = peopleIn(race);
      return cards.raceSection(race, people, { title: districtLabel(race), stateLink: false,
                                               fullOdds: true, moneyOpen: true,
                                               fold: foldable ? { short: shortLabel(race),
                                                 label: districtLabel(race), shared: shared } : null });
    }).join("");
    if (raceHtml) {
      /* Texas has 38 districts; a row of jump chips saves the scroll. With
       * several districts the House races are squares laid out as the
       * districts lie (VISUALS-27), the Senate's a chip beside them. */
      var tiles = houseRaces.length > 3 && KYC.districtTiles ? KYC.districtTiles(code, houseRaces) : "";
      var jumps = senateRaces.concat(tiles ? [] : houseRaces).map(function (race) {
        return '<a class="chip chip-link" href="#' + KYC.escapeAttr("race-" + race.id) + '" title="' +
          KYC.escapeAttr(districtLabel(race)) + '">' + KYC.escapeHtml(shortLabel(race)) + "</a>";
      }).join("");
      var all = senateRaces.length + houseRaces.length;
      var sharedLine = Object.keys(shared).map(function (k) { return cards.headBadgeHtml(shared[k]); }).join(" ");
      html.push(
        '<section class="state-section" id="races">',
        // Congress only, and it says so: a list that looked like the whole
        // ballot left out the governor, the legislature and every local race.
        '<h2 class="state-heading">2026 races for Congress in ' + KYC.escapeHtml(name) + "</h2>",
        '<p class="state-note">Each seat with the sitting member, everyone on the ' +
          "November ballot, and - folded under the race - everyone no longer running. " +
          alsoOnBallot(code, name, info.territory, keptMeasures) + "</p>",
        (senateRaces.length + houseRaces.length > 3 && jumps
          ? '<nav class="toolbar jump-row race-jumps" aria-label="Jump to a race">' + jumps + "</nav>"
          : ""),
        tiles ? '<div class="race-tiles">' + tiles + "</div>" : "",
        // On a phone (foldLayout): the badges every race shares, once, and
        // a way to open every race at once.
        foldable
          ? '<div class="race-fold-bar" hidden>' + (sharedLine
            ? '<p class="race-shared">All ' + all + " races: " + sharedLine + "</p>" : "") +
            raceFilterBar(senateRaces.concat(houseRaces)) +
            '<button type="button" class="btn race-open-all" data-race-open-all>Open all ' + all +
            " races</button></div>"
          : "",
        raceHtml,
        "</section>"
      );
    }
    if (govRace) html.push(governorSection(foldable));
    if (measures) html.push(measures);

    target.innerHTML = html.join("");
    if (KYC.findRep) KYC.findRep.mountAll(target);
    if (foldable) initFold();
  }

  /** The race for governor: the election office's list as cards
   *  (KYC.stategov.governorRace, the map's and the grid's too, rule 12).
   *  Where the races for Congress fold to rows on a phone, it folds the
   *  same way, its row in the race's own words (governorRowWords, rule
   *  99), apart from their count: it is no race for Congress (rule 73). */
  function governorSection(foldable) {
    var heading = KYC.stategov.raceHeading(code);
    var body = KYC.stategov.governorRace(code);
    var inner = foldable
      ? '<section class="gov-race-fold gov-race-foldable" id="race-governor" data-race="governor">' +
        governorRow(KYC.stategov.governorRowWords(code), heading) +
        '<div class="race-body" id="race-body-governor">' + body +
        '<p class="race-close-row" hidden><button type="button" class="btn race-close" data-race-close="governor">' +
        KYC.icon("chevron", "race-close-icon") + " Close the " + KYC.escapeHtml(heading.replace(/^2026 /, "")) +
        "</button></p></div></section>"
      : body;
    return '<section class="state-section gov-race-section" id="governor-race">' +
      '<h2 class="state-heading">' + KYC.escapeHtml(heading) + "</h2>" + inner + "</section>";
  }

  /** The race for governor folded to one row, in the form of a race for
   *  Congress's (KYC.cards.raceRow): the holder line, then each group of
   *  names under its own label. Drawn hidden; foldLayout shows it. */
  function governorRow(words, heading) {
    var groups = words.ballot.map(function (g) {
      return '<span class="race-row-ballot"><span class="race-row-label">' + KYC.escapeHtml(g[0]) +
        ":</span> " + g[1].map(function (name) {
          return '<span class="race-row-name">' + KYC.escapeHtml(name) + "</span>";
        }).join(", ") + ".</span> ";
    }).join("");
    return '<h3 class="race-row-title" hidden><button type="button" class="race-row" aria-expanded="true" ' +
      'aria-controls="race-body-governor" data-race-toggle="governor">' +
      '<span class="race-row-num is-word" aria-hidden="true">Gov.</span>' +
      '<span class="race-row-main"><span class="sr-only">' + KYC.escapeHtml(heading) + ". </span>" +
      (words.held ? '<span class="race-row-held">' + KYC.escapeHtml(words.held) + "</span> " : "") +
      groups + (words.none ? '<span class="race-row-ballot">' + KYC.escapeHtml(words.none) + "</span>" : "") +
      "</span>" + KYC.icon("chevron", "race-row-chevron") + "</button></h3>";
  }

  /** What else the state's November 3 ballot elects, from the same table the
   *  State government section marks, in a sentence. This site lists the
   *  candidates for Congress only, and says so. The statewide questions,
   *  where its ballot holds them, are listed in their own section (rule 95),
   *  and the sentence points there. *kept*: the plain list the page was
   *  written with holds questions, where the data file did not load. */
  function alsoOnBallot(code, name, territory, kept) {
    var words = officesAlso(code, name, territory);
    if (!kept && !KYC.ballot.hasMeasures(code)) return words;
    var section = KYC.ballot.measuresName(code);
    return words + " The ballot's " + KYC.escapeHtml(section.toLowerCase()) + " are listed under " +
      '<a class="state-jump" href="#measures">' + KYC.escapeHtml(section) + "</a>.";
  }

  function officesAlso(code, name, territory) {
    var list = KYC.stategov ? KYC.stategov.ballotList(code) : null;
    // The words the Your ballot page says too (kyc-ballot.js, rule 12).
    var rest = KYC.ballot.unlisted;
    if (code === "DC") return KYC.ballot.dcContests();
    if (territory) {
      // A territory's own record covers its governor only (ballot2026.TERRITORIES):
      // its legislature and local offices are not in it, and are said so.
      var named = KYC.stategov && KYC.stategov.listsCandidates(code, { governor: false });
      return (list
        ? "Of the territorial offices this site covers, the same ballot also elects the " +
          KYC.escapeHtml(list.replace(/^the /, "")) + " (see " +
          '<a class="state-jump" href="#state-government">Territorial government</a>' +
          (named ? ", which lists the candidates for " + KYC.escapeHtml(named) : "") + "). " +
          governorWhere(code, "The candidates for governor are under ")
        : list === "" ? KYC.escapeHtml(name) + " does not elect its governor in 2026. " : "") +
        KYC.escapeHtml(KYC.ballot.territoryUnlisted);
    }
    if (list === null) {
      return "Your ballot may also hold local contests, which this site does not list.";
    }
    if (!list) {
      return "None of " + KYC.escapeHtml(KYC.possessive(name)) + " governor, lieutenant governor, attorney " +
        "general, secretary of state or regular legislative seats is elected in 2026; the " +
        "ballot may still hold " + rest + ".";
    }
    // The statewide offices' candidates are listed under State government
    // from the election office's own list (rule 91); the legislature's are
    // not, and the sentence says which.
    // The governor's are in the race for governor's own section, below.
    var listed = KYC.stategov && KYC.stategov.listsCandidates(code, { governor: false });
    var governor = governorWhere(code, "");
    var where = [governor ? "those for governor under " + governor : "",
      listed ? "those for " + KYC.escapeHtml(listed) + " under State government" : ""].filter(Boolean);
    return "Of the state offices this site covers, the same ballot also elects " +
      KYC.escapeHtml(list) + " (see " +
      '<a class="state-jump" href="#state-government">State government</a>). It may also hold ' +
      rest + ". " + (where.length
        ? "This site lists the candidates for Congress here, " + (where.length > 1 ? where[0] + ", and " +
          where[1] : "and " + where[0]) + "; not those for the legislature."
        : "This site lists the candidates for Congress only.");
  }

  /** A link to the race for governor's section by its heading, after
   *  *lead*, where the page draws it and the election office's list was
   *  read; "" otherwise. */
  function governorWhere(code, lead) {
    if (!(KYC.stategov && KYC.stategov.governorListed(code))) return "";
    return lead + '<a class="state-jump" href="#governor-race">' +
      KYC.escapeHtml(KYC.stategov.raceHeading(code)) + "</a>" + (lead ? ". " : "");
  }

  /* A link to a section of this page ("#state-government", from the guide)
   * arrives before the script has drawn that section, so the browser's own
   * jump finds nothing. Jump once it is there, then drop the fragment: left
   * in the address, closing a profile returned to it and jumped the reader
   * back to the section, however far they had read on. */
  function jumpToSection() {
    // "#findrep?zip=43215" is the legislature and county pages' link to this
    // page's members of Congress: the ZIP code the reader gave there is
    // asked here, not lost (PR #104 review). A fragment is never sent to a
    // server, and it is dropped from the address below.
    var m = /^#([A-Za-z][\w-]*)(?:\?zip=(\d{5}))?$/.exec(global.location.hash);
    if (!m) return;
    var section = doc.getElementById(m[1]);
    if (!section) return;
    // A race reached by a link (a shared race's page, the lookup's answer,
    // Your ballot, a district page) opens where the page folds.
    var race = (section.closest && section.closest(FOLDS)) || ownFold(section);
    if (race && fold && fold.phone && !filterPasses(race)) setRaceFilter("all", true);
    if (race && fold && fold.phone) setOpen(race, true, "reader");
    var jump = function () {
      barForJump(section);
      if (section.scrollIntoView) section.scrollIntoView({ block: "start" });
    };
    jump();
    holdPlace(jump);
    if (m[2] && m[1] === "findrep" && KYC.findRep) KYC.findRep.ask(m[2]);
    if (global.history && global.history.replaceState) {
      global.history.replaceState(global.history.state, "", global.location.pathname + global.location.search);
      // The races still picked out, as the address said before the jump.
      if (raceFilter !== "all") KYC.router.writeFilters({ races: raceFilter });
    }
  }

  /* What is drawn above a section goes on growing for a moment after the
   * jump - portraits, the voting block, the district squares - and a shared
   * race's link (r/<raceId>.html, rule 96) left a phone 3,000px above
   * CA-22, on CA-19's money, with the fragment already dropped (PR #121
   * review). So the jump is made again each time the page's content
   * changes size, until the reader scrolls, taps or types, or the page has
   * been drawing for HOLD_MS. */
  var HOLD_MS = 10000;
  var HOLD_STOPS = ["wheel", "touchstart", "pointerdown", "keydown"];

  function holdPlace(jump) {
    var Observer = global.ResizeObserver;
    var content = el("stateContent");
    if (!Observer || !content) return;
    var done = false;
    var observer = new Observer(function () { if (!done) jump(); });
    var stop = function () {
      if (done) return;
      done = true;
      observer.disconnect();
      clearTimeout(timer);
      HOLD_STOPS.forEach(function (name) { global.removeEventListener(name, stop, true); });
    };
    var timer = setTimeout(stop, HOLD_MS);
    HOLD_STOPS.forEach(function (name) {
      global.addEventListener(name, stop, { capture: true, passive: true });
    });
    observer.observe(content);
  }

  /* ---------------------------------------------------------- all states */

  function renderIndex() {
    var target = el("stateContent");
    var states = KYC.meta().states || {};
    var codes = Object.keys(states).sort(function (a, b) {
      return states[a].name.localeCompare(states[b].name);
    });
    doc.title = "States & territories — Know Your Candidate";

    var rows = codes.map(function (c) {
      var info = states[c];
      var seats = seatWords(info);
      var off = offCycle(info);
      return [
        '<a class="state-row" href="' + KYC.escapeAttr(KYC.stateUrl(c)) + '" data-state="' + KYC.escapeAttr(c) + '">',
        '<span class="state-row-name">' + KYC.escapeHtml(info.name) +
          ' <span class="state-row-code">' + KYC.escapeHtml(c) + "</span></span>",
        '<span class="state-row-meta">' + KYC.escapeHtml(seats.join(", ")) + "</span>",
        off
          ? '<span class="state-row-meta">' + KYC.escapeHtml(off) + '</span><span class="state-row-meta"></span>'
          : '<span class="state-row-meta">' + KYC.escapeHtml(plural(info.seatsUp, "seat") +
            (KYC.recordPhase() ? " on the 2026 ballot" : " up")) +
            (info.open ? " &middot; " + KYC.escapeHtml(plural(info.open, "open seat")) : "") + "</span>" +
            '<span class="state-row-meta">' +
            KYC.escapeHtml(runningWords(info, KYC.recordPhase()).join(" · ")) + "</span>",
        "</a>",
      ].join("");
    });

    target.innerHTML = [
      '<header class="state-hero">',
      '<h1 class="state-title">States &amp; territories</h1>',
      '<p class="state-summary">One page each: who holds the seats, the 2026 races, and everyone who has filed.</p>',
      "</header>",
      // Every page at its place on a map-like grid (VISUALS-35).
      KYC.statePicker ? KYC.statePicker() : "",
      // The list of states is right here: no "How to vote" link to this page.
      '<section class="state-section findrep" id="findrep" data-findrep data-findrep-list></section>',
      '<div class="state-list" id="stateList">' + rows.join("") + "</div>",
    ].join("");
    if (KYC.findRep) KYC.findRep.mountAll(target);
  }

  /* --------------------------------------------------------------- chrome */

  /* Where the races fold, the page search opens the races holding someone
   * it matches, keeps the rows whose own words match (a holder running
   * elsewhere, a name the results give with no profile here) and hides the
   * rest; cleared, it folds back only the races it opened. A desktop's
   * races are not hidden, as before. */
  function searchRaces(q) {
    if (!fold || !fold.phone) return;
    var folded = KYC.foldText(q || "");
    foldSections().forEach(function (section) {
      var id = section.getAttribute("data-race");
      // A race the filter leaves out stays out, whatever the search finds.
      var kept = filterPasses(section);
      if (!q) {
        section.hidden = !kept;
        if (fold.opened[id] === "search") setOpen(section, false);
        return;
      }
      var hit = Array.prototype.some.call(section.querySelectorAll(".race-body .card"), function (c) {
        var cell = c.parentNode && c.parentNode.classList.contains("card-cell") ? c.parentNode : c;
        return !cell.hidden;
      });
      var row = section.querySelector(".race-row");
      var named = !hit && !!row && KYC.foldText(row.textContent).indexOf(folded) !== -1;
      section.hidden = (!hit && !named) || !kept;
      if (hit && kept && !fold.opened[id]) setOpen(section, true, "search");
      if ((!hit || !kept) && fold.opened[id] === "search") setOpen(section, false);
    });
    filterStatus();
  }

  function searchDelegation(q) {
    var grid = el("delegationCards");
    if (!fold || !fold.phone || !grid) return;
    var hit = !!q && Array.prototype.some.call(grid.children, function (cell) { return !cell.hidden; });
    if (hit && !fold.delegation) setDelegation(true, "search");
    if (!hit && fold.delegation === "search") setDelegation(false);
  }

  function searchQuery() {
    var input = el("stateSearch");
    return input ? input.value.trim().toLowerCase() : "";
  }

  function initSearch() {
    var input = el("stateSearch");
    if (!input) return;
    var run = KYC.debounce(function () {
      var q = input.value.trim().toLowerCase();
      if (kind === "states") {
        // Folded like every other search on the site (KYC.foldText).
        var folded = KYC.foldText(q);
        Array.prototype.forEach.call(doc.querySelectorAll(".state-row"), function (row) {
          row.hidden = !!folded && KYC.foldText(row.textContent).indexOf(folded) === -1;
        });
        return;
      }
      Array.prototype.forEach.call(doc.querySelectorAll("#stateContent .card"), function (c) {
        var item = KYC.byId(c.getAttribute("data-id"));
        // A sitting member's card sits in a cell beside its contact link
        // (KYC.cards.card): hide the cell, or the link stays on screen with
        // no name beside it.
        var cell = (c.parentNode && c.parentNode.classList &&
          c.parentNode.classList.contains("card-cell")) ? c.parentNode : c;
        cell.hidden = !!q && !(item && KYC.matchesQuery(item, q));
      });
      searchDelegation(q);
      searchRaces(q);
    }, 120);
    input.addEventListener("input", run);
  }

  /* A link to a race on this very page, written as the page's own address
   * (the lookup's answer: "../states/ca.html#race-H-CA-27-2026"). */
  function samePageRace(a) {
    return !!a && a.pathname === global.location.pathname && /^#race-/.test(a.hash || "");
  }

  function initCards() {
    el("stateContent").addEventListener("click", function (event) {
      // A folded race's row opens or folds it, in place; its Close button
      // folds it and puts the reader back on its row.
      var toggle = event.target.closest("[data-race-toggle]");
      if (toggle) {
        var own = toggle.closest(FOLDS);
        setOpen(own, toggle.getAttribute("aria-expanded") !== "true", "reader");
        return;
      }
      var close = event.target.closest("[data-race-close]");
      if (close) {
        var closing = close.closest(FOLDS);
        setOpen(closing, false);
        // At once, as every jump on this page is (goTo).
        barForJump(closing);
        if (closing.scrollIntoView) closing.scrollIntoView({ block: "start", behavior: "auto" });
        closing.querySelector(".race-row").focus({ preventScroll: true });
        return;
      }
      var members = event.target.closest("[data-delegation-toggle]");
      if (members) {
        setDelegation(members.getAttribute("aria-expanded") !== "true", "reader");
        return;
      }
      if (event.target.closest("[data-jump-find]")) {
        // Back to the block, ready to pick again from its select.
        goTo("find-race");
        var picker = el("raceJumpSelect");
        if (picker && picker.focus) picker.focus({ preventScroll: true });
        return;
      }
      var filter = event.target.closest("[data-race-filter]");
      if (filter) {
        setRaceFilter(filter.getAttribute("data-race-filter"));
        // "Show all" goes back to the chips it undid.
        if (filter.classList.contains("race-filter-all")) {
          var chip = doc.querySelector('.race-filters [data-race-filter="all"]');
          if (chip) chip.focus();
        }
        return;
      }
      if (event.target.closest("[data-race-open-all]")) {
        var sections = shownSections();
        var all = sections.every(function (s) { return !!fold.opened[s.getAttribute("data-race")]; });
        sections.forEach(function (s) { setOpen(s, !all, "reader"); });
        return;
      }
      // A jump within the page scrolls there and leaves the address alone.
      // A fragment left in it sent the reader back to that section when a
      // profile closed, however far they had read on (as jumpToSection says).
      var jump = event.target.closest('.jump-row a[href^="#"], a.state-jump[href^="#"]');
      var link = jump || event.target.closest("a[href]");
      if (jump || samePageRace(link)) {
        var id = jump ? jump.getAttribute("href").slice(1) : link.hash.slice(1);
        if (doc.getElementById(id)) {
          event.preventDefault();
          goTo(id);
        }
        return;
      }
      var card = event.target.closest("[data-id]");
      if (card) KYC.profile.open(card.getAttribute("data-id"));
    });
  }

  function applyRoute(route) {
    if (route.view === "profile" && KYC.profile.open(route.id, { fromRoute: true })) return;
    if (KYC.profile.isOpen()) KYC.profile.close();
    // The races the address picks out (#/?races=open), where the page folds.
    if (fold && route.view === "list") setRaceFilter(route.params.races || "all", true);
  }

  KYC.ready(function () {
    if (!data.length) {
      // Said above the plain lists the page was written with (rule 96),
      // which stay: they are this build's names, and all a reader can have.
      el("stateContent").insertAdjacentHTML("afterbegin", '<p class="results-bar">' +
        KYC.escapeHtml(KYC.peopleProblem() ||
        "Profile data did not load. Run: python build_profile_site.py") + "</p>");
      return;
    }
    KYC.profile.ensure();
    if (kind === "states") renderIndex(); else { renderState(); jumpToSection(); }
    initSearch();
    initCards();
    if (fold) {
      initJumpSelect();
      initFoldEvents();
    }
    KYC.router.onChange(function () { applyRoute(KYC.router.read()); });
    applyRoute(KYC.router.read());
  });
})(window);
